const escapeHTML = (value = "") =>
  String(value).replace(/[&<>"']/g, (character) => {
    const entities = {
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#39;",
    };

    return entities[character];
  });

const createPosterImage = (title, mediaLabel) => {
  const palette = {
    Anime: ["#0f2b65", "#5b21b6"],
    Drama: ["#831843", "#be123c"],
    Manga: ["#115e59", "#0e7490"],
    "Light Novel": ["#7c2d12", "#c2410c"],
  }[mediaLabel] || ["#1e3a8a", "#4338ca"];
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 800"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${palette[0]}"/><stop offset="1" stop-color="${palette[1]}"/></linearGradient></defs><rect width="600" height="800" fill="url(#g)"/><circle cx="480" cy="170" r="190" fill="#fff" opacity=".08"/><circle cx="95" cy="690" r="230" fill="#fff" opacity=".07"/><path d="M0 525 Q180 410 330 540 T600 510 V800 H0Z" fill="#07152f" opacity=".34"/><text x="48" y="90" fill="#dbeafe" font-family="Arial,sans-serif" font-size="22" font-weight="700" letter-spacing="5">FLIPPLAY · ${escapeHTML(mediaLabel).toUpperCase()}</text><foreignObject x="48" y="330" width="500" height="280"><div xmlns="http://www.w3.org/1999/xhtml" style="font:700 42px/1.14 Arial,sans-serif;color:white;text-shadow:0 3px 12px #0f172a;text-wrap:balance">${escapeHTML(title)}</div></foreignObject></svg>`;
  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
};

const getCatalogImage = (item, mediaLabel) =>
  item.images?.webp?.large_image_url || item.images?.jpg?.large_image_url || createPosterImage(item.title, mediaLabel);

const updateServicePosters = () => {
  document.querySelectorAll("[data-service-media]").forEach((image) => {
    const type = image.dataset.serviceMedia;
    const item = catalogData.find((catalogItem) => catalogItem.type === type && (catalogItem.images?.webp?.large_image_url || catalogItem.images?.jpg?.large_image_url));
    const label = type === "manga" ? "Manga" : "Light Novel";
    const title = item?.title || (type === "manga" ? "Manga pilihan" : "Light Novel pilihan");
    image.src = item ? getCatalogImage(item, label) : createPosterImage(title, label);
    image.alt = item ? `Sampul ${label}: ${item.title}` : `Ilustrasi layanan ${label}`;
  });
};

const renderCatalog = (catalog) => {
  if (catalog.length === 0) {
    animeGrid.innerHTML = `
      <p class="col-span-full rounded-xl bg-white p-8 text-center text-gray-600 shadow-sm">
        Tidak ada judul yang cocok. Coba kategori, tema, atau kata kunci lain.
      </p>
    `;
    return;
  }

  animeGrid.innerHTML = catalog
    .map(({ title, images, score, year, episodes, type, format }) => {
      const imageUrl = images?.webp?.large_image_url || images?.jpg?.large_image_url || "";
      const rating = score ?? "Belum tersedia";
      const mediaLabel = {
        anime: "Anime",
        drama: format || "Film / Series",
        manga: "Manga",
        "light-novel": "Light Novel",
      }[type] || "Katalog";
      const details = [mediaLabel, year, episodes ? `${episodes} episode` : null].filter(Boolean).join(" · ");

      const poster = `
          <img
            src="${escapeHTML(imageUrl || createPosterImage(title, mediaLabel))}"
            alt="Poster ${escapeHTML(title)}"
            loading="lazy"
            class="h-64 w-full bg-gray-100 object-cover"
          >
        `;

      return `
        <article class="overflow-hidden rounded-2xl border border-gray-100 bg-white shadow-md transition hover:-translate-y-1 hover:shadow-xl">
          ${poster}
          <div class="p-5">
            <div class="mb-3 flex items-start justify-between gap-3">
              <h3 class="line-clamp-2 text-lg font-bold text-gray-900">${escapeHTML(title)}</h3>
              <span class="shrink-0 rounded-full bg-amber-100 px-2.5 py-1 text-sm font-bold text-amber-800" aria-label="Rating ${escapeHTML(rating)} dari 10">
                ★ ${escapeHTML(rating)}
              </span>
            </div>
            <p class="text-sm text-gray-500">${escapeHTML(details || "Detail belum tersedia")}</p>
          </div>
        </article>
      `;
    })
    .join("");
  animeGrid.querySelectorAll("img").forEach((image) => {
    image.addEventListener("error", () => {
      if (image.dataset.fallbackApplied) return;
      image.dataset.fallbackApplied = "true";
      const title = image.alt.replace(/^Poster /, "");
      const item = catalogData.find((catalogItem) => catalogItem.title === title);
      const mediaLabel = item?.type === "manga" ? "Manga" : item?.type === "light-novel" ? "Light Novel" : item?.type === "drama" ? "Drama" : "Anime";
      image.src = createPosterImage(title, mediaLabel);
    }, { once: true });
  });
  updateServicePosters();
};

const updateAnimeGrid = () => {
  const searchTerm = searchInput.value.trim().toLocaleLowerCase();
  const auraTheme = {
    1: "action",
    4: "comedy",
    8: "drama",
  }[activeGenreId];
  const filteredCatalog = catalogData.filter((item) => {
    const matchesTitle = item.title.toLocaleLowerCase().includes(searchTerm);
    const matchesMedia = activeMediaType === "all" || item.type === activeMediaType;
    const itemThemes = item.themes || [];
    const matchesTheme = activeTheme === null || itemThemes.includes(activeTheme);
    const matchesGenre =
      activeGenreId === null ||
      (item.genres || []).some(({ mal_id }) => mal_id === activeGenreId) ||
      (auraTheme && itemThemes.includes(auraTheme));

    return matchesTitle && matchesMedia && matchesTheme && matchesGenre;
  });

  const sourceNotice = animeSource === "live"
    ? "Anime, manga, dan light novel memakai gambar Jikan bila tersedia; drama memakai katalog lokal."
    : `Semua kategori memakai data contoh lokal. ${animeNotice}`;

  animeStatus.textContent = `${filteredCatalog.length} judul ditemukan. ${sourceNotice}`;
  renderCatalog(filteredCatalog);
};

const loadAnime = async () => {
  animeStatus.textContent = "Loading data...";
  retryButton.classList.add("hidden");
  animeSource = "loading";
  animeNotice = "";
  animeGrid.innerHTML = `
    <p class="col-span-full text-center text-gray-600">Loading data...</p>
  `;
  searchInput.disabled = true;
  const abortController = new AbortController();
  const requestTimeout = setTimeout(() => abortController.abort(), 20000);
  [...auraButtons, ...mediaButtons, ...themeButtons].forEach((button) => {
    button.disabled = true;
  });

  try {
    const response = await fetch(API_URL, { signal: abortController.signal });
    if (!response.ok) {
      throw new Error(`Permintaan gagal dengan status ${response.status}.`);
    }

    const { data } = await response.json();
    const liveAnime = data.map((anime) => ({
      ...anime,
      type: "anime",
      themes: (anime.genres || []).map(({ name }) => name.toLocaleLowerCase().replaceAll(" ", "-")),
    }));

    const fetchJikanCollection = async (path, type) => {
      try {
        const collectionResponse = await fetch(`https://api.jikan.moe/v4/${path}`, { signal: abortController.signal });
        if (!collectionResponse.ok) return [];
        const result = await collectionResponse.json();
        return (result.data || []).map((item) => ({
          ...item,
          type,
          title: item.title || item.title_english || "Tanpa judul",
          year: item.published?.from?.slice(0, 4) || "",
          format: type === "manga" ? "Manga" : "Light Novel",
          themes: [...(item.genres || []), ...(item.themes || [])]
            .map(({ name }) => name.toLocaleLowerCase().replaceAll(" ", "-")),
        }));
      } catch (collectionError) {
        if (collectionError.name !== "AbortError") console.warn(`Gagal memuat sampul ${type} dari Jikan:`, collectionError);
        return [];
      }
    };

    // Jikan membatasi laju permintaan; beri jeda kecil di antara endpoint katalog.
    await new Promise((resolve) => setTimeout(resolve, 400));
    const liveManga = await fetchJikanCollection("manga?type=manga&order_by=score&sort=desc&limit=8", "manga");
    await new Promise((resolve) => setTimeout(resolve, 400));
    const liveLightNovels = await fetchJikanCollection("manga?type=lightnovel&order_by=score&sort=desc&limit=8", "light-novel");
    const localNonAnime = LOCAL_CATALOG.filter((item) => item.type !== "anime");
    catalogData = [
      ...liveAnime,
      ...localNonAnime.filter((item) => item.type === "drama"),
      ...(liveManga.length ? liveManga : localNonAnime.filter((item) => item.type === "manga")),
      ...(liveLightNovels.length ? liveLightNovels : localNonAnime.filter((item) => item.type === "light-novel")),
    ];
    animeSource = "live";
    animeNotice = "";
    searchInput.disabled = false;
    [...auraButtons, ...mediaButtons, ...themeButtons].forEach((button) => {
      button.disabled = false;
    });
    updateAnimeGrid();
  } catch (error) {
    console.error("Gagal memuat data anime:", error);
    const reason = error.name === "AbortError"
      ? "Permintaan ke Jikan API timeout setelah 20 detik"
      : error instanceof TypeError
        ? "Jikan API tidak dapat dijangkau"
        : `Jikan API gagal: ${error.message}`;

    catalogData = LOCAL_CATALOG;
    animeSource = "fallback";
    animeNotice = `${reason}; data anime bukan hasil live.`;
    searchInput.disabled = false;
    [...auraButtons, ...mediaButtons, ...themeButtons].forEach((button) => {
      button.disabled = false;
    });
    retryButton.classList.remove("hidden");
    animeStatus.textContent = `${reason}. Menampilkan katalog contoh lokal; data bukan hasil live.`;
    updateAnimeGrid();
  } finally {
    clearTimeout(requestTimeout);
  }
};

retryButton.addEventListener("click", loadAnime);
searchInput.addEventListener("input", updateAnimeGrid);

const updateFilterButton = (button, isActive, activeClasses, inactiveClasses) => {
  button.setAttribute("aria-pressed", String(isActive));
  activeClasses.forEach((className) => button.classList.toggle(className, isActive));
  inactiveClasses.forEach((className) => button.classList.toggle(className, !isActive));
};

mediaButtons.forEach((button) => {
  button.addEventListener("click", () => {
    activeMediaType = button.dataset.mediaType;
    mediaButtons.forEach((mediaButton) => {
      const isActive = mediaButton.dataset.mediaType === activeMediaType;
      updateFilterButton(
        mediaButton,
        isActive,
        ["bg-blue-600", "text-white", "border-blue-600"],
        ["bg-white", "text-blue-800", "border-blue-200"],
      );
    });
    updateAnimeGrid();
  });
});

themeButtons.forEach((button) => {
  button.addEventListener("click", () => {
    activeTheme = activeTheme === button.dataset.theme ? null : button.dataset.theme;
    themeButtons.forEach((themeButton) => {
      const isActive = themeButton.dataset.theme === activeTheme;
      updateFilterButton(
        themeButton,
        isActive,
        ["bg-indigo-600", "text-white", "border-indigo-600"],
        ["bg-white", "text-indigo-800", "border-indigo-200"],
      );
    });
    updateAnimeGrid();
  });
});

auraButtons.forEach((button) => {
  button.addEventListener("click", () => {
    const selectedGenreId = Number(button.dataset.genreId);
    activeGenreId = activeGenreId === selectedGenreId ? null : selectedGenreId;

    auraButtons.forEach((auraButton) => {
      const isActive = Number(auraButton.dataset.genreId) === activeGenreId;
      updateFilterButton(
        auraButton,
        isActive,
        ["bg-blue-600", "text-white", "border-blue-600"],
        ["bg-white", "text-blue-800", "border-blue-200"],
      );
    });

    updateAnimeGrid();
  });
});

const menuButton = document.getElementById("menu-btn");
const mobileMenu = document.getElementById("mobile-menu");

if (menuButton && mobileMenu) {
  menuButton.addEventListener("click", () => {
    const isOpening = mobileMenu.classList.contains("hidden");
    mobileMenu.classList.toggle("hidden");
    mobileMenu.classList.toggle("flex");
    mobileMenu.classList.toggle("flex-col");
    mobileMenu.classList.toggle("absolute");
    mobileMenu.classList.toggle("top-16");
    mobileMenu.classList.toggle("left-0");
    mobileMenu.classList.toggle("w-full");
    mobileMenu.classList.toggle("bg-blue-600");
    mobileMenu.classList.toggle("p-6");
    mobileMenu.classList.toggle("shadow-md");
    menuButton.setAttribute("aria-expanded", String(isOpening));
  });

  mobileMenu.querySelectorAll("a").forEach((link) => {
    link.addEventListener("click", () => {
      if (!mobileMenu.classList.contains("hidden")) {
        menuButton.click();
      }
    });
  });
}

