const getTrailerSearchUrl = (title) => `https://www.youtube.com/results?search_query=${encodeURIComponent(`${title} official trailer`)}`;

const enrichCatalogItem = async (item) => {
  if (!item || item.type === "drama" || item.metadataLoaded) return;
  item.metadataLoaded = true;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 5000);
  try {
    const query = encodeURIComponent(item.title);
    const type = item.type === "light-novel" ? "lightnovel" : "manga";
    const response = await fetch(`https://api.jikan.moe/v4/manga?q=${query}&type=${type}&limit=1`, { signal: controller.signal });
    if (!response.ok) return;
    const result = await response.json();
    const remoteItem = result.data?.[0];
    if (!remoteItem) return;
    Object.assign(item, remoteItem, {
      title: item.title,
      type: item.type,
      synopsis: remoteItem.synopsis || item.synopsis,
      year: remoteItem.published?.from?.slice(0, 4) || item.year,
      images: remoteItem.images || item.images,
      score: remoteItem.score || item.score,
      chapters: remoteItem.chapters || item.chapters,
      url: remoteItem.url || item.url,
    });
  } catch (error) {
    console.info("Metadata tambahan tidak tersedia:", error.message);
  } finally {
    clearTimeout(timeout);
  }
};

const openCatalogDetail = async (item) => {
  if (!item) return;
  await enrichCatalogItem(item);
  const copy = DETAIL_COPY[item.title] || {};
  const imageUrl = item.images?.webp?.large_image_url || item.images?.jpg?.large_image_url || "";
  const trailerYoutubeId = item.trailer?.youtube_id || "";
  const trailerUrl = item.trailer?.url || item.trailerUrl || copy.trailerUrl || getTrailerSearchUrl(item.title);
  const synopsis = item.synopsis || (typeof copy === "string" ? copy : copy.synopsis) || "Sinopsis belum tersedia untuk judul ini.";
  const mediaLabel = { anime: "Anime", drama: item.format || "Film / Series", manga: "Manga", "light-novel": "Light Novel" }[item.type] || "Katalog";
  const metadata = [mediaLabel, item.year, item.episodes ? `${item.episodes} episode` : null, item.chapters ? `${item.chapters} chapter` : null, item.score ? `★ ${item.score}` : null].filter(Boolean).join(" · ");
  const video = trailerYoutubeId
    ? `<div class="flipplay-detail-video"><iframe src="https://www.youtube.com/embed/${encodeURIComponent(trailerYoutubeId)}" title="Trailer ${escapeHTML(item.title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div>`
    : imageUrl
      ? `<img class="flipplay-detail-poster" src="${escapeHTML(imageUrl)}" alt="Poster ${escapeHTML(item.title)}">`
      : `<div class="flex h-56 w-full items-center justify-center bg-gradient-to-br from-blue-950 via-blue-700 to-indigo-500 p-8 text-center text-xl font-bold text-white">${escapeHTML(item.title)}</div>`;

  detailDialog.innerHTML = `<div class="flipplay-detail-body"><button class="flipplay-detail-close" type="button" aria-label="Tutup detail">×</button>${video}<div class="flipplay-detail-content"><p class="mb-2 text-xs font-bold uppercase tracking-widest text-blue-600">${escapeHTML(mediaLabel)}</p><h2 id="flipplay-detail-title" class="mb-2 text-2xl font-bold text-gray-900">${escapeHTML(item.title)}</h2><p class="flipplay-detail-meta mb-5">${escapeHTML(metadata || "Detail katalog")}</p><h3 class="mb-2 text-lg font-bold text-gray-900">Sinopsis</h3><p class="flipplay-detail-synopsis mb-6">${escapeHTML(synopsis)}</p><a class="flipplay-detail-link" href="${escapeHTML(trailerUrl)}" target="_blank" rel="noreferrer">${trailerYoutubeId ? "Buka trailer di YouTube" : "Cari trailer / sumber"} ↗</a></div></div>`;
  detailDialog.querySelector(".flipplay-detail-close").addEventListener("click", () => detailDialog.close());
  detailDialog.showModal();
};

const enhanceCatalogCards = () => {
  animeGrid.querySelectorAll("article").forEach((card) => {
    if (card.dataset.detailsReady === "true") return;
    const title = card.querySelector("h3")?.textContent.trim();
    const item = findCatalogItemByTitle(title);
    if (!item) return;
    card.dataset.detailsReady = "true";
    const actions = document.createElement("div");
    actions.className = "flipplay-card-actions";
    actions.innerHTML = `<button class="flipplay-card-detail" type="button">Lihat sinopsis & trailer</button>`;
    actions.querySelector("button").addEventListener("click", () => openCatalogDetail(item));
    card.querySelector(".p-5")?.append(actions);
  });
};

const catalogObserver = new MutationObserver(enhanceCatalogCards);
catalogObserver.observe(animeGrid, { childList: true, subtree: true });
enhanceCatalogCards();
